head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gPageSize = 10; //페이지 size
scwin.gTotalCnt = 0; //전체 row
scwin.gPageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gLdMktTp = js_market;
scwin.gLastJob = "조회";
scwin.vScrenID = 'ULDSTF35115.xml';X < !불성실지정예고--;
클릭-- > function() {
    /*
    		// 일자 체크
    		if( getObjectValue(edt_ToDate).length < 8) {
    			alert("일자 올바르게 입력하십시오." );
    			edt_ToDate.focus();
    			return;		
    		}	
    */
    fn_Search();
} < !불성실지정--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    txb_TotalCnt.setValue("총건수 : ");
    var url_list = "/UnfaithfulDesign.do?method=listUnfaithfulKosdaq&inputMessageId=NFAITHKOSDAQCOND_IN" + "&outputMessageId=NFAITHKOSDAQLIST_OUT";
    var url_cond = "&FROM_DATE=" + "20130729" + "&TO_DATE=" + "99991231" + "&LIST_STAT=1" + "&LIMIT_ISU_YN=Y" + "&LD_MKT_TP=" + scwin.gLdMktTp + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.gPageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;



    // 그리드의 데이타 조회
    dts_nfaith_list.DataID = encodeURI(url_list + url_cond);
    dts_nfaith_list.reset();
    $c.cm.ShowWin(dts_nfaith_list);
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_nfaith_list.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_nfaith_list.getCellData(eval(obj), "ISUR_CD");
    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.fn_insert = async function(GridID, row, colid) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    if (colid == "SEL_FUNC") {
        var res = window.confirm("추가 하시겠습니까?");
        if (res) {
            var lmtDd = "";
            scwin.gLastJob = "추가";
            if (objDataID.getCellData(row, "ACNTCLS_MMDD1") == "Y") {
                lmtDd = parseInt((objDataID.getCellData(row, "DESIGN_DD")).substr(0, 4)) + parseInt(1);
                lmtDd = lmtDd + "1231";
            } else {
                lmtDd = "";
            }
            var url = "/UnfaithfulDesign.do?method=insertUnfaithfulLimitIsur";
            url += "&REG_EMP_NO=" + js_emp_no;
            url += "&ACPT_NO=" + objDataID.getCellData(row, "ACPT_NO");
            url += "&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD");
            url += "&PRFM_FC_DISCLS_VIOL_YN=Y";
            url += "&DISCLS_SUBMIT_LMT_DD=" + lmtDd;
            dts_nfaith_list.DataID = encodeURI(url);
            dts_nfaith_list.Reset();
            opener.fn_CheckCond();
            await $c.frame.CloseFrame();
        }
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DESIGN_DD") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, 'R');
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.dts_nfaith_list_OnLoadError = function() {
    $c.stf.alert_error(dts_nfaith_list);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_nfaith_list_OnLoadCompleted = function(rowcount) {
    if (dts_nfaith_list.errorMsg) {
        $c.win.alert(dts_nfaith_list.errorMsg);
    } else {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
        //alert(txb_TotalCnt.value );

    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    scwin.fn_insert(grd_Grid, row, colid);
};
scwin.gform_onload = function() {
    //fn_SetCode();
    fn_CheckCond();
};
